namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Bio { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public int InstructorId { get; set; }
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Student name is required.")]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }

    public DateTime SubmittedAt { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." }
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Alice Johnson", Title = "Professor of Computer Science", Bio = "Dr. Johnson has over 20 years of experience in software engineering and artificial intelligence research. She has published numerous papers on machine learning and distributed systems.", Email = "ajohnson@university.edu" },
            new() { Id = 2, Name = "Dr. Robert Smith", Title = "Associate Professor of Mathematics", Bio = "Dr. Smith specializes in applied mathematics and statistics. He has been teaching at the university for 15 years and is known for making complex topics accessible.", Email = "rsmith@university.edu" }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, DepartmentId = 1, Title = "Introduction to Programming", Code = "CS101", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "MWF 10:00-10:50 AM", InstructorId = 1, IsFeatured = true },
            new() { Id = 2, DepartmentId = 1, Title = "Data Structures and Algorithms", Code = "CS201", Description = "Study fundamental data structures including arrays, linked lists, trees, and graphs. Analyze algorithm complexity and design efficient solutions.", Credits = 4, Schedule = "TTh 1:00-2:15 PM", InstructorId = 1, IsFeatured = true },
            new() { Id = 3, DepartmentId = 1, Title = "Database Systems", Code = "CS310", Description = "Introduction to database design, SQL, normalization, and transaction management. Includes hands-on projects with relational databases.", Credits = 3, Schedule = "MWF 2:00-2:50 PM", InstructorId = 1, IsFeatured = false },
            new() { Id = 4, DepartmentId = 2, Title = "Calculus I", Code = "MATH101", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.", Credits = 4, Schedule = "MWF 9:00-9:50 AM", InstructorId = 2, IsFeatured = true },
            new() { Id = 5, DepartmentId = 2, Title = "Linear Algebra", Code = "MATH202", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications to computer science and physics.", Credits = 3, Schedule = "TTh 10:30-11:45 AM", InstructorId = 2, IsFeatured = false },
            new() { Id = 6, DepartmentId = 2, Title = "Statistics and Probability", Code = "MATH301", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "MWF 11:00-11:50 AM", InstructorId = 2, IsFeatured = false },
            new() { Id = 7, DepartmentId = 3, Title = "General Physics I", Code = "PHYS101", Description = "Mechanics, thermodynamics, and waves. Includes laboratory sessions with hands-on experiments.", Credits = 4, Schedule = "TTh 9:00-10:15 AM", InstructorId = 2, IsFeatured = true },
            new() { Id = 8, DepartmentId = 3, Title = "Electromagnetism", Code = "PHYS202", Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves. Advanced laboratory work included.", Credits = 4, Schedule = "MWF 1:00-1:50 PM", InstructorId = 2, IsFeatured = false },
            new() { Id = 9, DepartmentId = 1, Title = "Web Application Development", Code = "CS350", Description = "Modern web development using ASP.NET Core, Blazor, and cloud deployment. Full-stack development with C#.", Credits = 3, Schedule = "TTh 2:30-3:45 PM", InstructorId = 1, IsFeatured = true }
        };
    }

    public List<Department> GetDepartments() => _departments.ToList();

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
            query = query.Where(c =>
                c.Title.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(search, StringComparison.OrdinalIgnoreCase));

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public Instructor? GetInstructor(int id) => _instructors.FirstOrDefault(i => i.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public void SubmitEnrollment(EnrollmentRequest request)
    {
        request.SubmittedAt = DateTime.Now;
        _enrollments.Add(request);
    }
}

