@page "/courses"
@rendermode InteractiveServer
@inject CatalogService CatalogService

<PageTitle>Browse Courses</PageTitle>

<h1>Browse Courses</h1>

<div class="row mb-3">
    <div class="col-md-6">
        <input type="text" class="form-control" placeholder="Search by title or code..."
               @bind="searchTerm" @bind:event="oninput" />
    </div>
    <div class="col-md-4">
        <select class="form-select" @bind="selectedDepartmentId">
            <option value="0">All Departments</option>
            @foreach (var dept in departments)
            {
                <option value="@dept.Id">@dept.Name</option>
            }
        </select>
    </div>
</div>

<table class="table table-striped">
    <thead>
        <tr>
            <th>Code</th>
            <th>Title</th>
            <th>Credits</th>
            <th>Department</th>
            <th></th>
        </tr>
    </thead>
    <tbody>
        @foreach (var course in filteredCourses)
        {
            <tr>
                <td>@course.Code</td>
                <td>@course.Title</td>
                <td>@course.Credits</td>
                <td>@(departments.FirstOrDefault(d => d.Id == course.DepartmentId)?.Name)</td>
                <td><a href="/courses/@course.Id">Details</a></td>
            </tr>
        }
    </tbody>
</table>

@if (!filteredCourses.Any())
{
    <p>No courses found matching your criteria.</p>
}

@code {
    [SupplyParameterFromQuery]
    public int? departmentId { get; set; }

    private string searchTerm = string.Empty;
    private int selectedDepartmentId;
    private List<Department> departments = new();
    private List<Course> filteredCourses => CatalogService.GetCourses(
        string.IsNullOrWhiteSpace(searchTerm) ? null : searchTerm,
        selectedDepartmentId > 0 ? selectedDepartmentId : null);

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
        if (departmentId.HasValue)
            selectedDepartmentId = departmentId.Value;
    }
}

@page "/courses/{Id:int}"
@inject CatalogService CatalogService

<PageTitle>@(course?.Title ?? "Course Not Found")</PageTitle>

@if (course is null)
{
    <h1>Course Not Found</h1>
    <p>The requested course could not be found.</p>
    <a href="/courses">Back to course list</a>
}
else
{
    <h1>@course.Title</h1>
    <p><strong>Code:</strong> @course.Code</p>
    <p><strong>Department:</strong> @(department?.Name ?? "Unknown")</p>
    <p><strong>Credits:</strong> @course.Credits</p>
    <p><strong>Schedule:</strong> @course.Schedule</p>
    <p><strong>Description:</strong> @course.Description</p>

    @if (instructor is not null)
    {
        <h2>Instructor</h2>
        <p><strong>Name:</strong> @instructor.Name</p>
        <p><strong>Title:</strong> @instructor.Title</p>
        <p><strong>Bio:</strong> @instructor.Bio</p>
        <p><strong>Email:</strong> <a href="mailto:@instructor.Email">@instructor.Email</a></p>
    }

    <a href="/enroll?courseId=@course.Id" class="btn btn-success mt-3">Enroll in this Course</a>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Course? course;
    private Department? department;
    private Instructor? instructor;

    protected override void OnInitialized()
    {
        course = CatalogService.GetCourse(Id);
        if (course is not null)
        {
            department = CatalogService.GetDepartment(course.DepartmentId);
            instructor = CatalogService.GetInstructor(course.InstructorId);
        }
    }
}

@page "/enroll"
@inject CatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>Enrollment request submitted successfully!</h4>
        <p>Thank you, @FormModel.StudentName. Your request to enroll has been received.</p>
        <a href="/courses">Browse more courses</a>
    </div>
}
else
{
    <EditForm Model="FormModel" OnValidSubmit="HandleSubmit" FormName="enrollment">
        <DataAnnotationsValidator />
        <ValidationSummary />

        <div class="mb-3">
            <label for="studentName" class="form-label">Student Name</label>
            <InputText id="studentName" class="form-control" @bind-Value="FormModel.StudentName" />
            <ValidationMessage For="() => FormModel.StudentName" />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <InputText id="studentId" class="form-control" @bind-Value="FormModel.StudentId" />
            <ValidationMessage For="() => FormModel.StudentId" />
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <InputSelect id="courseId" class="form-select" @bind-Value="FormModel.CourseId">
                <option value="0">-- Select a course --</option>
                @foreach (var course in courses)
                {
                    <option value="@course.Id">@course.Code - @course.Title</option>
                }
            </InputSelect>
            <ValidationMessage For="() => FormModel.CourseId" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
    </EditForm>
}

@code {
    [SupplyParameterFromQuery]
    public int? courseId { get; set; }

    [SupplyParameterFromForm]
    private EnrollmentRequest FormModel { get; set; } = new();

    private List<Course> courses = new();
    private bool submitted;

    protected override void OnInitialized()
    {
        courses = CatalogService.GetCourses(null, null);
        if (courseId.HasValue && FormModel.CourseId == 0)
            FormModel.CourseId = courseId.Value;
    }

    private void HandleSubmit()
    {
        CatalogService.SubmitEnrollment(FormModel);
        submitted = true;
    }
}

